// else none (nullptr: the bot keeps its legacy forecast and evaluation).
#ifndef FUSION_MODELS_REGISTRY_HPP
#define FUSION_MODELS_REGISTRY_HPP
// FUSION_MAX_WIDTH_REQUIRED=1024
// This must precede the inference headers; an explicit smaller build fails their model assertions.
#ifndef FUSION_MAX_WIDTH
#define FUSION_MAX_WIDTH 1024
#endif
#include "weights_general.hpp"

namespace fusion::models {

inline constexpr int kRegistryRequiredMaxWidth = 1024;

struct ModelSet { const char* id; const PolicyModelP3* policy; const ValueModel* value; double alpha; int adapter; };

inline const ModelSet* forTeams(int teams) {
    static const ModelSet table[16] = {
    {nullptr, nullptr, nullptr, 0.0, 0},
    {nullptr, nullptr, nullptr, 0.0, 0},
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[2], general::kAdapter},  // 2 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[3], general::kAdapter},  // 3 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[4], general::kAdapter},  // 4 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[5], general::kAdapter},  // 5 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[6], general::kAdapter},  // 6 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[7], general::kAdapter},  // 7 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[8], general::kAdapter},  // 8 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[9], general::kAdapter},  // 9 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[10], general::kAdapter},  // 10 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[11], general::kAdapter},  // 11 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[12], general::kAdapter},  // 12 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[13], general::kAdapter},  // 13 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[14], general::kAdapter},  // 14 teams
    {"general", &general::kPolicy, &general::kValue, general::kAlpha[15], general::kAdapter},  // 15 teams
    };
    return teams >= 2 && teams <= 15 && table[teams].policy ? &table[teams] : nullptr;
}

}  // namespace fusion::models
#endif  // FUSION_MODELS_REGISTRY_HPP
